/// it as `predictor_l1_sass_provenance_missing` (the tracer did
/// not classify the cache operator for this instruction).
///
/// Per AGENTS.md wire-extension policy, this is an additive enum
/// extension: producer emits the new values, consumer accepts them;
/// old readers that only know the enum entries at producer-side
/// build time route unknown values through their catch-all path.
/// The 12 named values mirror the JSON schema's
/// `instruction_cache_op` enum at
/// the trace cache-op schema (closed-set
/// lockstep enforced by a structural cross-surface parity test).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum InstructionCacheOp {
    Unspecified = 0,
    LdgECa = 1,
    LdgECg = 2,
    LdgECs = 3,
    LdgEEf = 4,
    LdgEStrongSm = 5,
    LdgEStrongGpu = 6,
    Ldl = 7,
    Stl = 8,
    Ldgsts = 9,
    Atom = 10,
    Tex = 11,
    Other = 12,
}
impl InstructionCacheOp {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "INSTRUCTION_CACHE_OP_UNSPECIFIED",
            Self::LdgECa => "INSTRUCTION_CACHE_OP_LDG_E_CA",
            Self::LdgECg => "INSTRUCTION_CACHE_OP_LDG_E_CG",
            Self::LdgECs => "INSTRUCTION_CACHE_OP_LDG_E_CS",
            Self::LdgEEf => "INSTRUCTION_CACHE_OP_LDG_E_EF",
            Self::LdgEStrongSm => "INSTRUCTION_CACHE_OP_LDG_E_STRONG_SM",
            Self::LdgEStrongGpu => "INSTRUCTION_CACHE_OP_LDG_E_STRONG_GPU",
            Self::Ldl => "INSTRUCTION_CACHE_OP_LDL",
            Self::Stl => "INSTRUCTION_CACHE_OP_STL",
            Self::Ldgsts => "INSTRUCTION_CACHE_OP_LDGSTS",
            Self::Atom => "INSTRUCTION_CACHE_OP_ATOM",
            Self::Tex => "INSTRUCTION_CACHE_OP_TEX",
            Self::Other => "INSTRUCTION_CACHE_OP_OTHER",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "INSTRUCTION_CACHE_OP_UNSPECIFIED" => Some(Self::Unspecified),
            "INSTRUCTION_CACHE_OP_LDG_E_CA" => Some(Self::LdgECa),
            "INSTRUCTION_CACHE_OP_LDG_E_CG" => Some(Self::LdgECg),
            "INSTRUCTION_CACHE_OP_LDG_E_CS" => Some(Self::LdgECs),
            "INSTRUCTION_CACHE_OP_LDG_E_EF" => Some(Self::LdgEEf),
            "INSTRUCTION_CACHE_OP_LDG_E_STRONG_SM" => Some(Self::LdgEStrongSm),
            "INSTRUCTION_CACHE_OP_LDG_E_STRONG_GPU" => Some(Self::LdgEStrongGpu),
            "INSTRUCTION_CACHE_OP_LDL" => Some(Self::Ldl),
            "INSTRUCTION_CACHE_OP_STL" => Some(Self::Stl),
            "INSTRUCTION_CACHE_OP_LDGSTS" => Some(Self::Ldgsts),
            "INSTRUCTION_CACHE_OP_ATOM" => Some(Self::Atom),
            "INSTRUCTION_CACHE_OP_TEX" => Some(Self::Tex),
            "INSTRUCTION_CACHE_OP_OTHER" => Some(Self::Other),
            _ => None,
        }
    }
}
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Warp {
    #[prost(int32, tag = "1")]
    pub id: i32,
    #[prost(message, repeated, tag = "2")]
    pub instructions: ::prost::alloc::vec::Vec<Instruction>,
}
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Threadblock {
    #[prost(message, optional, tag = "1")]
    pub block_id: ::core::option::Option<Dim3d>,
    #[prost(btree_map = "int32, message", tag = "2")]
    pub warps: ::prost::alloc::collections::BTreeMap<i32, Warp>,
}
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct Trace {
    #[prost(string, tag = "1")]
    pub name: ::prost::alloc::string::String,
    #[prost(int32, tag = "2")]
    pub binary_version: i32,
    #[prost(string, tag = "3")]
    pub nvbit_version: ::prost::alloc::string::String,
    #[prost(int32, tag = "4")]
    pub accelsim_version: i32,
    #[prost(bool, tag = "5")]
    pub is_gathered_registers_values: bool,
    #[prost(btree_map = "int64, message", tag = "6")]
    pub gpu_device: ::prost::alloc::collections::BTreeMap<i64, GpuDevice>,
    /// Trace-contract identity + capability. Net-new with the ASYNC_COPY+ATOM
    /// address-carrying contract transition (additive, per the AGENTS.md wire-
    /// extension policy). `trace_contract_id` names the emitted contract so an
    /// old exclusion-semantics trace (field absent/empty) is never silently
    /// cross-compared with a new address-carrying one. `memory_payload_classes`
    /// lists the MemoryOpClass values for which this trace emits address records
    /// under the contract (e.g. \[GLOBAL, SHARED, LOCAL, ATOMIC, ASYNC_COPY\] post-
    /// flip); its ABSENCE is the legacy signal the consumer identity gates use to
    /// skip the widened ATOMIC/ASYNC enforcement on pre-transition traces.
    #[prost(string, tag = "7")]
    pub trace_contract_id: ::prost::alloc::string::String,
    #[prost(enumeration = "MemoryOpClass", repeated, tag = "8")]
    pub memory_payload_classes: ::prost::alloc::vec::Vec<i32>,
    /// Additive capability vocabulary for architecture-specific payloads.  These
    /// strings are descriptive capabilities, not admission gates.  In
    /// particular an SM120 trace may advertise that TMA transfers live in the
    /// sidecar, that cache operators are present on ordinary memory records, and
    /// that register snapshots are intentionally unavailable.
    #[prost(string, repeated, tag = "9")]
    pub trace_capabilities: ::prost::alloc::vec::Vec<::prost::alloc::string::String>,
}
